def hidden_rule_fn(state):
    n = len(state)
    # Determine if n is prime
    def is_prime(k):
        if k < 2:
            return False
        for i in range(2, int(k**0.5) + 1):
            if k % i == 0:
                return False
        return True

    last = state[-1]
    second_last = state[-2]

    if is_prime(n):
        # XOR of last two elements, mod 7
        new_val = (last ^ second_last) % 7
    else:
        # grolp-sum: sum of last two + 3, mod 7
        new_val = (last + second_last + 3) % 7

    return state + [new_val]
